declare(strict_types=1);define('HWC_SKIP_GLOBAL_SHELL',true);require_once __DIR__.'/config/dynamic_forms.php';$pdo=role_portal_db();dynamic_forms_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user||(string)$user['role_code']!=='admin'){header('Location: access_denied.php');exit;}$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();$error=null;
try{if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$name=trim((string)($_POST['form_name']??''));$key=preg_replace('/[^a-z0-9_]+/','_',strtolower(trim((string)($_POST['form_key']??''))));$key=trim((string)$key,'_');if($name===''||$key==='')throw new RuntimeException('Form name and unique key are required.');$s=$pdo->prepare("INSERT INTO dynamic_form_definitions(organization_id,form_key,form_name,target_page,description,sort_order,status,is_custom,created_by,updated_by) VALUES(?,?,?,'dynamic_form_entry.php',?,?,'active',1,?,?)");$s->execute([$orgId,$key,$name,trim((string)($_POST['description']??'')),(int)($_POST['sort_order']??100),(int)$user['id'],(int)$user['id']]);security_step17_audit($pdo,(int)$user['id'],'custom_form_created','dynamic_form',(int)$pdo->lastInsertId(),['form_key'=>$key]);header('Location: form_designer.php?form='.rawurlencode($key));exit;}}catch(Throwable $e){$error=$e->getMessage();}$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Custom Form</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fd;color:#294036;font-family:Inter,Arial}.wrap{max-width:850px;margin:auto;padding:24px}.card{padding:22px;border:1px solid #dce6e0;border-radius:18px;background:#fff}.card h1{margin:0}.card p{color:#708078}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.grid label{display:grid;gap:5px;font-size:.72rem;font-weight:800}.wide{grid-column:1/-1}input,textarea{padding:11px;border:1px solid #d7e1dc;border-radius:10px}textarea{min-height:100px}button{grid-column:1/-1;padding:12px;border:0;border-radius:10px;background:#5744db;color:#fff;font-weight:850}.bad{padding:10px;background:#fff0f0;color:#a13a3a;border-radius:9px;margin-bottom:12px}@media(max-width:650px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><main class="wrap"><section class="card"><h1>Create New Data Form</h1><p>Create the form first; Designer will open automatically so you can add fields and dropdown options.</p><?php if($error):?><div class="bad"><?=$h($error)?></div><?php endif?><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><label>Form Name<input name="form_name" placeholder="Daily Club Visit" required></label><label>Unique Form Key<input name="form_key" placeholder="daily_club_visit" required></label><label class="wide">Description<textarea name="description" placeholder="What information will this form collect?"></textarea></label><label>Display Order<input type="number" name="sort_order" value="100"></label><button>Create Form & Open Designer</button></form></section></main></body></html>
